/* Independent Workouts implementation. No One data or styling is imported. */
const WORKOUT_STORAGE='form.lab.workouts.v1';
let workoutData={routines:[],history:[],session:null},workoutView='routines',workoutQuery='',workoutDetail=null,workoutDraft=null,workoutNotice='';
const WORKOUT_BACKUP=WORKOUT_STORAGE+'.backup';
let storageReadBlocked=false,storageDirty=false;
try{
 const raw=localStorage.getItem(WORKOUT_STORAGE);
 if(raw!==null)workoutData=readWorkoutData(raw);
 else {const backup=localStorage.getItem(WORKOUT_BACKUP);if(backup!==null){workoutData=readWorkoutData(backup);workoutNotice='Recovered workout data from backup.'}}
}catch{
 storageReadBlocked=true;
 try{const backup=localStorage.getItem(WORKOUT_BACKUP);if(backup!==null){workoutData=readWorkoutData(backup);workoutNotice='Recovered backup. Original data is preserved; saving is disabled until recovery is reviewed.'}else workoutNotice='Saved workout data could not be read. Saving is disabled to protect it.'}
 catch{workoutNotice='Saved workout data could not be read. Saving is disabled to protect it.'}
}
const escapeWorkout=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const workoutId=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const workoutClone=v=>JSON.parse(JSON.stringify(v));
const demoPreferenceKey='form.lab.demo-mode.v1',demoDataKey='form.lab.demo-workouts.v1',demoDraftKey='form.lab.demo-draft.v1';
let demoMode=false,realWorkoutData=null;
function saveWorkouts(){if(demoMode){try{localStorage.setItem(demoDataKey,JSON.stringify(workoutData));workoutNotice='';return true}catch{workoutNotice='Could not save demo workout.';return false}}
 storageDirty=true;
 if(storageReadBlocked){workoutNotice='Saving is disabled to protect unreadable original workout data.';return false}
 try{
  if(!validWorkoutData(workoutData))throw Error('Invalid workout data');
  const previous=localStorage.getItem(WORKOUT_STORAGE);
  if(previous!==null){readWorkoutData(previous);try{localStorage.setItem(WORKOUT_BACKUP,previous)}catch{}}
  localStorage.setItem(WORKOUT_STORAGE,JSON.stringify({...workoutData,schemaVersion:1}));
  storageDirty=false;workoutNotice='';return true
 }catch{workoutNotice='Could not save on this device. Keep the app open.';return false}
}
const draftKey='form.lab.routine-draft.v1';
let draftBlocked=false,draftDirty=false;
try{const raw=localStorage.getItem(draftKey);if(raw){const d=JSON.parse(raw);if(!validRecord(d))throw Error('Invalid draft');workoutDraft=d;workoutNotice='Recovered unsaved routine.'}}catch{draftBlocked=true;workoutNotice='Draft recovery unavailable; original draft preserved.'}
function persistDraft(){if(demoMode){try{if(workoutDraft)localStorage.setItem(demoDraftKey,JSON.stringify(workoutDraft));else localStorage.removeItem(demoDraftKey)}catch{workoutNotice='Could not save demo draft.'}return;}if(draftBlocked)return;try{if(workoutDraft)localStorage.setItem(draftKey,JSON.stringify(workoutDraft));else localStorage.removeItem(draftKey);draftDirty=false}catch{draftDirty=true;workoutNotice='Could not save routine draft.'}}
function readDemo(){const raw=localStorage.getItem(demoDataKey);return raw?readWorkoutData(raw):workoutClone(window.FORM_DEMO)}
function activateDemo(){const data=readDemo(),raw=localStorage.getItem(demoDraftKey),draft=raw?JSON.parse(raw):null;if(draft&&!validRecord(draft))throw Error('Invalid demo draft');realWorkoutData=workoutData;workoutData=data;workoutDraft=draft;demoMode=true;globalThis.formDemoMode=true}
try{if(localStorage.getItem(demoPreferenceKey)==='true'&&!workoutDraft&&!workoutData.session&&validWorkoutData(window.FORM_DEMO))activateDemo()}catch{}
const setCount=r=>r.exercises.reduce((n,e)=>n+e.sets.length,0);
const workoutMeta=r=>r.exercises.length+' exercise'+(r.exercises.length===1?'':'s')+' · '+setCount(r)+' sets';
const workoutAction=(label,action,extra='',secondary=false)=>'<button type="button" class="form-button workouts-action'+(secondary?' workouts-secondary':'')+'" data-w-action="'+action+'" '+extra+'>'+label+'</button>';
function workoutListItems(){
 const q=workoutQuery.trim().toLowerCase(),history=workoutView==='history',all=history?workoutData.history:workoutData.routines;
 const matches=all.filter(r=>(r.name+' '+(history?new Date(r.finished).toLocaleDateString()+' '+r.exercises.map(e=>e.name).join(' '):'')).toLowerCase().includes(q));
 const count=matches.length+' '+(history?'workout':'routine')+(matches.length===1?'':'s');
 let cards=matches.map(r=>'<button type="button" class="form-card workouts-card" data-w-action="'+(history?'history-detail':'routine-detail')+'" data-id="'+escapeWorkout(r.id)+'" aria-current="'+(workoutDetail?.id===r.id)+'"><strong>'+escapeWorkout(r.name)+'</strong><span class="workouts-muted">'+(history?Math.max(1,Math.round((r.finished-r.started)/60000))+' min · '+setCount(r)+' sets':workoutMeta(r))+'</span>'+(history?'<span class="workouts-muted">'+escapeWorkout(new Date(r.finished).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'}))+'</span>':'')+'</button>').join('');
 if(!cards)cards='<article class="form-card workouts-card"><h3>'+(all.length?'No matching '+(history?'workouts':'routines'):history?'No recorded workouts yet.':'Create your first routine')+'</h3><p class="workouts-muted">'+(all.length?'Try another search.':history?'Complete your first workout to see it here.':'Build your own training plan.')+'</p>'+(!history&&!all.length?workoutAction('Create Routine','new-routine'):'')+'</article>';
 return {cards,count};
}
function workoutListMarkup(){
 const {cards,count}=workoutListItems(),history=workoutView==='history';
 return '<section class="workouts-stack"><header class="workouts-header"><h1><span class="headline-leading" aria-hidden="true"></span>Workouts</h1><button type="button" class="workouts-round" data-w-action="new-routine" aria-label="Create Routine">'+icon('plus')+'</button></header><div class="workouts-segments" role="group" aria-label="Workout view"><button type="button" data-w-action="routines" aria-pressed="'+!history+'">Routines</button><button type="button" data-w-action="history" aria-pressed="'+history+'">History</button></div><label class="workouts-search">'+icon('search')+'<input id="workouts-search" type="search" placeholder="Search '+(history?'workouts':'routines')+'" aria-label="Search '+(history?'workouts':'routines')+'" value="'+escapeWorkout(workoutQuery)+'"></label><div class="workouts-section-title"><h2 class="workouts-heading">'+(history?'Recent history':'My routines')+'</h2><span id="workouts-count" class="workouts-muted" aria-live="polite">'+count+'</span></div><div id="workouts-items" class="workouts-card-list">'+cards+'</div>'+(!history?workoutAction(icon('play')+' Start Empty Workout','empty-workout','',true):'')+'</section>';
}
function workoutExerciseMarkup(e){
 return '<details class="workouts-card workouts-exercise"><summary><span class="form-artwork" data-artwork-id="'+escapeWorkout(e.exerciseId||'')+'"><span class="form-artwork-fallback">'+icon('exercise')+'</span></span><span class="workouts-exercise-copy"><strong>'+escapeWorkout(e.name)+'</strong><span class="workouts-muted workouts-exercise-meta">'+e.sets.length+' sets</span></span>'+icon('chevron-down')+'</summary><div class="workouts-set workouts-muted"><span>Set</span><span>kg</span><span>Reps</span><span>Rest</span></div>'+e.sets.map((t,i)=>'<div class="workouts-set"><span>'+(i+1)+'</span><span>'+escapeWorkout(t.weight)+'</span><span>'+escapeWorkout(t.reps)+'</span><span>'+escapeWorkout(t.rest)+'s</span></div>').join('')+'</details>';
}
function workoutDetailMarkup(r,history=false){
 return '<section class="workouts-detail"><header class="workouts-header"><div class="workouts-back"><button class="workouts-round" data-w-action="back" aria-label="Back to Workouts">'+icon('chevron-left')+'</button><h1>'+escapeWorkout(r.name)+'</h1></div>'+(!history?'<button class="workouts-round" data-w-action="edit-routine" aria-label="Edit Routine">'+icon('pencil')+'</button>':'')+'</header><p class="workouts-muted">'+workoutMeta(r)+(history?' · '+escapeWorkout(new Date(r.finished).toLocaleDateString()):'')+'</p>'+(!history?workoutAction('Start Workout','start-routine'):'')+'<h2 class="workouts-heading">Exercises</h2>'+r.exercises.map(workoutExerciseMarkup).join('')+(r.description?'<p class="workouts-muted">'+escapeWorkout(r.description)+'</p>':'')+'</section>';
}
const editorOpenCards=new WeakSet();
function workoutEditorMarkup(){
 const d=workoutDraft;
 return '<section class="workouts-detail workouts-editor one-editor"><header class="workouts-header"><div class="workouts-back"><button class="workouts-round" data-w-action="cancel-editor" aria-label="Back">'+icon('chevron-left')+'</button><input class="form-input workouts-input one-routine-title" aria-label="Routine name" data-w-field="name" value="'+escapeWorkout(d.name)+'" placeholder="Routine name"></div><button class="workouts-round" data-w-action="save-routine" aria-label="Save routine">'+icon('check')+'</button></header><p class="workouts-muted">'+workoutMeta(d)+'</p>'+workoutAction('Save Changes','save-routine')+'<div class="workouts-section-title"><h2 class="workouts-heading">Exercises</h2><button class="workouts-secondary" data-w-action="add-exercise">+ Add Exercise</button></div>'+d.exercises.map((e,i)=>'<details class="workouts-card workouts-exercise routine-exercise" data-routine-index="'+i+'" '+(editorOpenCards.has(e)?'open':'')+'><summary><span class="form-artwork" data-artwork-id="'+escapeWorkout(e.exerciseId||'')+'"><span class="form-artwork-fallback">'+icon('exercise')+'</span></span><span class="workouts-exercise-copy"><strong>'+escapeWorkout(e.name)+'</strong><span class="workouts-muted">'+e.sets.length+' sets</span></span>'+icon('chevron-down')+'</summary><div class="one-set-grid workouts-muted"><span>Set</span><span>kg</span><span>Reps</span><span>Rest</span><span></span></div>'+e.sets.map((t,j)=>'<div class="one-set-grid"><select aria-label="Set '+(j+1)+' type" data-w-field="type" data-e="'+i+'" data-s="'+j+'">'+['normal','warm-up','drop','failure','AMRAP'].map(v=>'<option value="'+v+'" '+((t.type||'normal')===v?'selected':'')+'>'+({normal:String(j+1),'warm-up':'W',drop:'D',failure:'F',AMRAP:'A'}[v])+'</option>').join('')+'</select>'+['weight','reps','rest'].map(k=>'<input class="form-input workouts-input" type="number" min="0" inputmode="decimal" aria-label="'+k+(k==='rest'?' seconds':'')+'" data-w-field="'+k+'" data-e="'+i+'" data-s="'+j+'" value="'+escapeWorkout(t[k])+'">').join('')+'<button class="workouts-secondary" data-w-action="remove-set" data-e="'+i+'" data-s="'+j+'" aria-label="Remove set '+(j+1)+'" '+(e.sets.length<=1?'disabled':'')+'>×</button></div>').join('')+workoutAction('+ Add Set','add-set','data-e="'+i+'"',true)+'<div class="routine-order"><button type="button" class="routine-grip" data-routine-grip="'+i+'" aria-label="Drag exercise to reorder">'+icon('grip-vertical')+'</button>'+workoutAction('Move up','move-up','data-e="'+i+'"',true)+workoutAction('Move down','move-down','data-e="'+i+'"',true)+'</div>'+workoutAction('Replace Exercise','replace-exercise','data-e="'+i+'"',true)+'<div class="routine-swipe-action">'+workoutAction('Remove Exercise','remove-exercise','data-e="'+i+'"',true)+'</div></details>').join('')+'<label>Description<input class="form-input workouts-input" data-w-field="description" value="'+escapeWorkout(d.description)+'" placeholder="Optional"></label>'+(workoutData.routines.some(r=>r.id===d.id)?workoutAction('Delete Routine','delete-routine','',true):'')+'</section>';
}
document.addEventListener('toggle',event=>{const el=event.target;if(!el.matches?.('.one-editor details[data-routine-index]')||!el.isConnected||!workoutDraft)return;const ex=workoutDraft.exercises[Number(el.dataset.routineIndex)];if(ex){if(el.open)editorOpenCards.add(ex);else editorOpenCards.delete(ex)}},true);
function workoutSessionMarkup(){
 const r=workoutData.session;return '<section class="workouts-detail"><header class="workouts-header"><h1>'+escapeWorkout(r.name)+'</h1><span class="workouts-muted">Active workout</span></header>'+r.exercises.map((e,i)=>'<article class="form-card workouts-card"><h3>'+escapeWorkout(e.name)+'</h3>'+e.sets.map((t,j)=>'<label class="workouts-session-set"><input type="checkbox" data-w-session="'+i+':'+j+'" '+(t.done?'checked':'')+'><span>Set '+(j+1)+' · '+escapeWorkout(t.weight)+' kg · '+escapeWorkout(t.reps)+' reps</span></label>').join('')+'</article>').join('')+workoutAction('Add Exercise','session-exercise','',true)+workoutAction('Finish Workout','finish-workout')+workoutAction('Discard Workout','discard-workout','',true)+'</section>';
}
let workoutsWide=false;
function isWorkoutsWide(){const root=document.documentElement;return root.clientWidth>root.clientHeight||matchMedia('(orientation: landscape)').matches}
function workoutsMarkup(){
 const wide=workoutsWide=isWorkoutsWide();
 let detail=workoutData.session?workoutSessionMarkup():workoutDraft?workoutEditorMarkup():workoutDetail?workoutDetailMarkup(workoutDetail,workoutView==='history'):'';
 return '<div class="page form-page workouts-page">'+(workoutNotice?'<p role="status" class="workouts-muted">'+escapeWorkout(workoutNotice)+'</p>':'')+'<div class="workouts-layout" data-wide="'+(wide&&!workoutData.session)+'">'+(!detail||wide&&!workoutData.session?workoutListMarkup():'')+detail+(!detail&&wide?'<section class="workouts-detail"><article class="workouts-card workouts-idle"><h3>'+(workoutView==='history'?'Workout details':'Routine details')+'</h3><p class="workouts-muted">Select '+(workoutView==='history'?'a workout':'a routine')+' to view its details.</p></article></section>':'')+'</div></div>';
}
function workoutRefresh(){persistDraft();const scroll=main.scrollTop;render();main.scrollTop=scroll}
function workoutStart(r){const previous=workoutData.session;workoutData.session={id:workoutId(),name:r.name,description:r.description||'',exercises:workoutClone(r.exercises),started:Date.now()};if(!saveWorkouts())workoutData.session=previous;workoutRefresh()}
function handleWorkoutAction(b){
 const action=b.dataset.wAction,e=Number(b.dataset.e),j=Number(b.dataset.s),id=b.dataset.id;
 if(workoutData.session&&!['session-exercise','finish-workout','discard-workout'].includes(action))return;
 if(workoutDraft&&['routines','history','routine-detail','history-detail','new-routine','empty-workout'].includes(action)&&!confirm('Discard unsaved routine changes?'))return;
 switch(action){
 case 'routines':case 'history':workoutView=action;workoutQuery='';workoutDetail=null;workoutDraft=null;break;
 case 'back':workoutDetail=null;break;
 case 'new-routine':workoutView='routines';workoutDetail=null;workoutDraft={id:workoutId(),name:'',description:'',exercises:[]};break;
 case 'routine-detail':case 'history-detail':workoutDraft=null;workoutView=action==='history-detail'?'history':'routines';workoutDetail=(workoutView==='history'?workoutData.history:workoutData.routines).find(r=>r.id===id)||null;break;
 case 'edit-routine':workoutDraft=workoutClone(workoutDetail);workoutDraft.exercises.forEach(x=>editorOpenCards.add(x));break;
 case 'cancel-editor':if(!confirm('Discard unsaved changes?'))return;workoutDraft=null;break;
 case 'add-exercise':{const draft=workoutDraft;openFormExercisePicker(xs=>{if(workoutDraft!==draft)return;const added=xs.map(x=>({...x,sets:[{weight:0,reps:10,rest:90}]}));added.forEach(x=>editorOpenCards.add(x));draft.exercises.push(...added);workoutRefresh()});return;}
 case 'replace-exercise':{const draft=workoutDraft,old=draft.exercises[e];openFormExercisePicker(xs=>{if(workoutDraft!==draft||draft.exercises[e]!==old)return;draft.exercises[e]={...old,...xs[0]};editorOpenCards.add(draft.exercises[e]);workoutRefresh()},{multi:false});return;}
 case 'move-up':case 'move-down':{const a=workoutDraft.exercises,to=e+(action==='move-up'?-1:1);if(e>=0&&e<a.length&&to>=0&&to<a.length)[a[e],a[to]]=[a[to],a[e]];break;}
 case 'remove-exercise':workoutDraft.exercises.splice(e,1);break;
 case 'add-set':workoutDraft.exercises[e].sets.push({...workoutDraft.exercises[e].sets.at(-1)||{weight:0,reps:10,rest:90}});break;
 case 'remove-set':if(workoutDraft.exercises[e].sets.length>1)workoutDraft.exercises[e].sets.splice(j,1);else workoutNotice='Keep at least one set per exercise.';break;
 case 'save-routine':{const d=workoutDraft;if(!d.name.trim()||d.exercises.some(x=>!x.name.trim()||!x.sets.length)){workoutNotice='Enter a routine name and give each exercise a name and at least one set.';break}d.name=d.name.trim();const i=workoutData.routines.findIndex(r=>r.id===d.id);const previous=workoutData.routines[i];if(i<0)workoutData.routines.push(d);else workoutData.routines[i]=d;if(saveWorkouts()){workoutDetail=d;workoutDraft=null}else{if(i<0)workoutData.routines.pop();else workoutData.routines[i]=previous; }break}
 case 'delete-routine':if(!confirm('Delete this routine?'))return;{const previous=workoutData.routines;workoutData.routines=previous.filter(r=>r.id!==workoutDraft.id);if(saveWorkouts()){workoutDraft=null;workoutDetail=null}else workoutData.routines=previous;break;}
 case 'start-routine':if(!workoutDetail.exercises.length){workoutNotice='Add an exercise before starting.';break}workoutStart(workoutDetail);return;
 case 'empty-workout':workoutDraft=null;workoutDetail=null;workoutStart({name:'Workout',exercises:[]});return;
 case 'session-exercise':{const session=workoutData.session;openFormExercisePicker(xs=>{if(workoutData.session!==session)return;const previous=session.exercises.slice();session.exercises.push(...xs.map(x=>({...x,sets:[{weight:0,reps:10,rest:90,done:false}]})));if(!saveWorkouts())session.exercises=previous;workoutRefresh()});return;}
 case 'finish-workout':{const r=workoutData.session,completed=r.exercises.map(x=>({...x,sets:x.sets.filter(t=>t.done)})).filter(x=>x.sets.length);if(!completed.length){workoutNotice='Complete at least one set before finishing.';break}const previous=workoutData.history;workoutData.history=[{...r,exercises:completed,finished:Date.now()},...previous];workoutData.session=null;if(saveWorkouts()){workoutDetail=null;workoutView='history';workoutQuery=''}else{workoutData.history=previous;workoutData.session=r}break}
 case 'discard-workout':if(!confirm('Discard this workout?'))return;{const previous=workoutData.session;workoutData.session=null;if(!saveWorkouts())workoutData.session=previous;break;}
 default:return;
 }
 workoutRefresh();
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-w-action]');if(b&&page==='Workouts')handleWorkoutAction(b)});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='workouts-search'){workoutQuery=t.value;const {cards,count}=workoutListItems();document.getElementById('workouts-items').innerHTML=cards;document.getElementById('workouts-count').textContent=count;return}if(!workoutDraft||!t.dataset.wField)return;const k=t.dataset.wField,i=Number(t.dataset.e),j=Number(t.dataset.s);if(k==='name'||k==='description')workoutDraft[k]=t.value;else if(k==='exercise'){const ex=workoutDraft.exercises[i];if(ex.name!==t.value){delete ex.exerciseId;delete ex.muscle;delete ex.equipment}ex.name=t.value;}else if(k==='type')workoutDraft.exercises[i].sets[j].type=t.value;else workoutDraft.exercises[i].sets[j][k]=Math.max(0,Number(t.value)||0);persistDraft()});
document.addEventListener('change',e=>{const t=e.target;if(!t.dataset.wSession||!workoutData.session)return;const [i,j]=t.dataset.wSession.split(':').map(Number);const set=workoutData.session.exercises[i].sets[j],previous=set.done;set.done=t.checked;if(!saveWorkouts()){set.done=previous;workoutRefresh()}});

function importHevy(raw){if(demoMode)throw Error('Turn off Demo Mode before importing.');
 if(workoutDraft||workoutData.session||storageReadBlocked||storageDirty)throw Error('Finish or save current work before importing.');
 const data=JSON.parse(raw);if(data.source!=='hevy'||!Array.isArray(data.routines)||!Array.isArray(data.workouts))throw Error('Invalid Hevy import file.');
 const num=v=>Number.isFinite(v)&&v>=0?v:0;
 const types={warmup:'warm-up',dropset:'drop',normal:'normal',failure:'failure'};
 const convert=(r,history)=>{if(typeof r.id!=='string'||typeof r.title!=='string'||!Array.isArray(r.exercises))throw Error('Invalid record');const record={id:'hevy-'+(history?'workout-':'routine-')+r.id,name:r.title,description:r.description||'',source:'hevy',sourceRecord:r,exercises:r.exercises.map(e=>({name:e.title,sourceExerciseId:e.exercise_template_id,notes:e.notes,supersetId:e.superset_id,sets:e.sets.map(t=>({weight:num(t.weight_kg),reps:num(t.reps??t.rep_range?.start),rest:num(e.rest_seconds),type:types[t.type]||'normal',...(history?{done:true}:{}),sourceSet:t}))}))};if(history){record.started=Date.parse(r.start_time);record.finished=Date.parse(r.end_time);if(!Number.isFinite(record.started)||!Number.isFinite(record.finished)||record.finished<record.started)throw Error('Invalid workout dates')}return record};
 const routines=data.routines.map(r=>convert(r,false)),history=data.workouts.map(r=>convert(r,true));if(!routines.every(validRecord)||!history.every(validRecord))throw Error('Invalid records');
 const merge=(old,incoming)=>{const seen=new Set(old.map(r=>r.id));return [...old,...incoming.filter(r=>{if(seen.has(r.id))return false;seen.add(r.id);return true})]};
 const previous=workoutData;workoutData={...previous,routines:merge(previous.routines,routines),history:merge(previous.history,history).sort((a,b)=>b.finished-a.finished)};
 const count=workoutData.routines.length-previous.routines.length,logs=workoutData.history.length-previous.history.length;if(!saveWorkouts()){workoutData=previous;throw Error('Import could not be saved.')}
 workoutNotice='Imported '+count+' routines and '+logs+' workouts.';page='Workouts';workoutView='routines';workoutDetail=null;render();return workoutNotice;
}
document.addEventListener('change',async e=>{if(e.target.id!=='hevy-import-file')return;const file=e.target.files?.[0];if(!file)return;try{if(file.size>20000000)throw Error('File too large');importHevy(await file.text())}catch(err){alert(err.message)}finally{e.target.value=''}});
function toggleDemo(){if(workoutDraft||workoutData.session||storageDirty||draftDirty||storageReadBlocked){alert('Finish or recover current work before switching modes.');return}if(!demoMode&&!validWorkoutData(window.FORM_DEMO)){alert('Demo data unavailable.');return}try{localStorage.setItem(demoPreferenceKey,String(!demoMode))}catch{alert('Could not remember Demo Mode on this device.');return}if(demoMode){workoutData=realWorkoutData;realWorkoutData=null;demoMode=false;globalThis.formDemoMode=false}else{try{activateDemo()}catch{localStorage.setItem(demoPreferenceKey,'false');alert('Demo data could not be loaded.');return}}workoutDetail=null;workoutQuery='';workoutView='routines';workoutNotice='';page='Workouts';render()}
document.addEventListener('click',e=>{if(e.target.closest('#demo-toggle'))toggleDemo()});
function setDiagnostics(value){showDiagnostics=Boolean(value);if(!showDiagnostics)delete document.body.dataset.safeOverlay;try{localStorage.setItem('form.diagnostics',String(showDiagnostics))}catch{}render()}
function render(){document.body.dataset.diagnostics=String(showDiagnostics);document.getElementById('build-tools').hidden=true;document.getElementById('viewport-lab').hidden=!showDiagnostics;window.resetFormExercisePicker?.();{main.innerHTML=page==='Home'?homeMarkup():page==='Workouts'?workoutsMarkup():'<div class="page form-page"><h1 class="brand"><span class="headline-leading" aria-hidden="true"></span>'+page+'</h1><p class="tagline">This page will follow One’s design when its turn comes.</p>'+(page==='Profile'?appearanceMarkup()+homeProfileMarkup()+'<article class="form-card workouts-card"><button type="button" id="profile-developer">Developer settings</button></article><article class="form-card workouts-card"><h2>Demo Mode</h2><button id="demo-toggle" type="button" aria-pressed="'+demoMode+'">'+(demoMode?'Turn off Demo Mode':'Turn on Demo Mode')+'</button><p>Sample workouts are separate from your saved data.</p><h2>Import Hevy data</h2><label>Choose private JSON file<input id="hevy-import-file" type="file" accept=".json,application/json"></label></article>':'')+'</div>'}document.querySelectorAll('button[data-go]').forEach(b=>b.setAttribute('aria-current',b.dataset.go===page?'page':'false'));const start=document.getElementById('home-start');if(start)start.onclick=()=>{if(!workoutDraft&&!workoutData.session){workoutView='routines';workoutDetail=null;workoutQuery=''}go('Workouts')};const calendar=document.getElementById('home-calendar');if(calendar)calendar.onclick=openRestDays;layout();installHeadingNavigation();main.querySelectorAll('[data-artwork-id]').forEach(el=>FormArtwork.mount(el,{exerciseId:el.dataset.artworkId}));window.lucide?.createIcons();diagnostics()}
function go(t){taps++;if(page!==t){page=t;render()}}
nav.innerHTML=tabs.map((t,i)=>'<button aria-label="'+t+'" title="'+t+'" data-go="'+t+'">'+icon(['home','workouts','progress','profile'][i])+'</button>').join('');

function installHeadingNavigation(){
 main.querySelector('.headline-build')?.remove();if(showDiagnostics)return;const heading=main.querySelector('h1');if(!heading)return;const label=document.createElement('button');label.type='button';label.className='headline-build';label.textContent=BUILD;label.setAttribute('aria-label','Build '+BUILD+' — check for updates');label.onclick=()=>{openDeveloper();update(true)};heading.append(label);
}
function openDeveloper(){dev.innerHTML='<h2>Developer settings</h2><label>Show diagnostics <input type="checkbox" id="show-diagnostics" '+(showDiagnostics?'checked':'')+'></label><label>Show safe area bars <input type="checkbox" id="show-safe-areas" '+(document.body.dataset.safeOverlay==='true'?'checked':'')+'></label><p>Build '+BUILD+'</p><button id="dev-update">Check for Updates</button><button id="dev-close">Done</button>';dev.showModal()}
let holdTimer=null,held=false,origin=null;function cancelHold(){clearTimeout(holdTimer);holdTimer=null}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('button[data-go="Profile"]'))return;held=false;origin=[e.clientX,e.clientY];cancelHold();holdTimer=setTimeout(()=>{held=true;openDeveloper()},3000)});document.addEventListener('pointermove',e=>{if(origin&&Math.hypot(e.clientX-origin[0],e.clientY-origin[1])>12)cancelHold()});for(const ev of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(ev,()=>{cancelHold();origin=null});document.addEventListener('contextmenu',e=>{if(e.target.closest('button[data-go="Profile"]'))e.preventDefault()});document.addEventListener('click',e=>{if(held&&e.target.closest('button[data-go="Profile"]')){held=false;e.preventDefault();e.stopImmediatePropagation()}},true);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='open-diagnostics'||b.id==='close-diagnostics'){setDiagnostics(b.id==='open-diagnostics');return}if(b.dataset.go){go(b.dataset.go);return}if(b.id==='check-update'||b.id==='dev-update'){update(true);return}if(b.id==='profile-developer')openDeveloper();if(b.id==='dev-close')dev.close();if(b.id==='home-coming-close')document.getElementById('home-coming').close()});dev.addEventListener('change',e=>{if(e.target.id==='show-safe-areas'){document.body.dataset.safeOverlay=String(e.target.checked);return}if(e.target.id==='show-diagnostics'){setDiagnostics(e.target.checked)}});
function adaptWorkoutsOrientation(){if(page!=='Workouts'||showDiagnostics||workoutsWide===isWorkoutsWide())return;const active=document.activeElement,field=active?.dataset?.wField,search=active?.id==='workouts-search',e=active?.dataset?.e,j=active?.dataset?.s,scroll=main.scrollTop;render();main.scrollTop=scroll;if(search)document.getElementById('workouts-search')?.focus({preventScroll:true});else if(field){const match=[...main.querySelectorAll('[data-w-field]')].find(t=>t.dataset.wField===field&&t.dataset.e===e&&t.dataset.s===j);match?.focus({preventScroll:true})}}
main.addEventListener('scroll',diagnostics,{passive:true});
let updateRequest=null,reloading=false;
function reloadLatest(){if(reloading)return;try{if(storageReadBlocked||draftBlocked)throw Error('Unreadable saved data');if(document.querySelector('dialog[open]'))throw Error('Close open dialog');if(workoutData.session||storageDirty){if(!saveWorkouts())throw Error('Workout save failed');const saved=readWorkoutData(localStorage.getItem(demoMode?demoDataKey:WORKOUT_STORAGE));if(JSON.stringify(saved.session)!==JSON.stringify(workoutData.session))throw Error('Session verification failed')}if(workoutDraft||draftDirty){persistDraft();const raw=localStorage.getItem(demoMode?demoDraftKey:draftKey);if(JSON.stringify(raw?JSON.parse(raw):null)!==JSON.stringify(workoutDraft)||draftDirty)throw Error('Draft verification failed')}}catch(e){document.getElementById('update-status').textContent='Update deferred · '+e.message;return}reloading=true;const target=new URL('index.html',location.href);target.searchParams.set('refresh',Date.now());location.replace(target.href)}
async function update(manual=false){if(reloading||(!manual&&document.hidden))return;const status=document.getElementById('update-status');if(manual)status.textContent='Checking…';if(!updateRequest){updateRequest=(async()=>{const url=new URL('version.json',location.href);url.searchParams.set('check',Date.now());const response=await fetch(url,{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const manifest=await response.json();if(!manifest||!Number.isSafeInteger(manifest.build)||manifest.build<1)throw Error('Invalid build');return manifest.build})().finally(()=>{updateRequest=null})}try{const latest=await updateRequest;if(latest>BUILD){status.textContent='Updating to Build '+latest+'…';reloadLatest()}else if(manual)status.textContent='Up to date · '+latest}catch(e){if(manual)status.textContent='Check failed · '+e.message}}
