let swipeOrigin=null;
document.addEventListener('touchstart',e=>{swipeOrigin=!showDiagnostics&&e.touches.length===1?[e.touches[0].clientX,e.touches[0].clientY]:null},{passive:true});
document.addEventListener('touchmove',e=>{if(showDiagnostics||!swipeOrigin||e.touches.length!==1)return;const t=e.touches[0],dx=Math.abs(t.clientX-swipeOrigin[0]),dy=Math.abs(t.clientY-swipeOrigin[1]);if(dx>8&&dx>dy&&e.cancelable)e.preventDefault()},{passive:false});
for(const type of ['touchend','touchcancel'])document.addEventListener(type,()=>{swipeOrigin=null},{passive:true});
