function railMeasure(){const n=nav.getBoundingClientRect();railReading.textContent='Right offset: '+railSlider.value+'px · center X: '+Math.round(n.x+n.width/2)+'px · viewport: '+document.documentElement.clientWidth+'px · orientation: '+(screen.orientation?.angle ?? window.orientation ?? 'unknown');}
