document.getElementById('rail-calibrate').onclick=()=>{const n=nav.getBoundingClientRect();const current=Math.round(document.documentElement.clientWidth-n.right);const approved=document.body.dataset.layout==='folded-landscape';const left=document.body.dataset.calibrating==='true'?Number(formSlider.value):approved?1:parseFloat(getComputedStyle(main).paddingLeft);const top=document.body.dataset.calibrating==='true'?Number(formSliderY.value):approved?24:parseFloat(getComputedStyle(main).paddingTop);document.body.dataset.calibrating='true';railPanel.hidden=false;formSet(Math.round(left));formSetY(Math.round(top));railSet(current)};
