/* One synchronous geometry pass per distinct viewport state; no animation or frame delay. */
let lastLayoutSignature=null;
let previousHingeMode=null,previousHingeRotation=null,hingeAnimations=[],hingeRects=[],hingeUntil=0;
function detectRotation(){
 const root=document.documentElement,v=window.visualViewport;
 const signature=JSON.stringify([root.clientWidth,root.clientHeight,screen.width,screen.height,currentRotation(),navigator.devicePosture?.type,matchMedia('(device-posture: folded)').matches,v?.width,v?.height,v?.scale,FormPosture.read()]);
 if(signature===lastLayoutSignature)return;
 lastLayoutSignature=signature;
 const posture=FormPosture.read(),rotation=currentRotation(),hingeChanged=previousHingeMode!==null&&previousHingeMode!==posture.mode&&previousHingeRotation===rotation;
 const rotated=previousHingeRotation!==null&&previousHingeRotation!==rotation;
 if(rotated)hingeUntil=0;
 if(hingeChanged)hingeUntil=performance.now()+(parseFloat(getComputedStyle(root).getPropertyValue('--motion-hinge-retarget-ms'))||500);
 const animateHinge=!rotated&&performance.now()<hingeUntil&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
 previousHingeMode=posture.mode;previousHingeRotation=rotation;
 const cards=[...main.querySelectorAll('.home-workout-card,.home-streak-card')];
 const before=animateHinge?cards.map((el,i)=>hingeChanged&&hingeRects[i]?.el===el?hingeRects[i].rect:el.getBoundingClientRect()):[];
 if(animateHinge||rotated){hingeAnimations.forEach(a=>a.cancel());hingeAnimations=[];}
 layout();adaptWorkoutsOrientation();installHeadingNavigation();
 hingeRects=cards.map(el=>({el,rect:el.getBoundingClientRect()}));
 if(animateHinge){
 const tokens=getComputedStyle(document.documentElement),duration=parseFloat(tokens.getPropertyValue(posture.mode==='flat'?'--unfold-motion-ms':'--hinge-motion-ms'))||320,easing=tokens.getPropertyValue(posture.mode==='flat'?'--unfold-motion-easing':'--hinge-motion-easing').trim()||'ease-out';
 cards.forEach((el,i)=>{const old=before[i],next=el.getBoundingClientRect();if(!old||!next.width||!next.height||!el.isConnected||!el.animate)return;
 const dx=old.left-next.left,dy=old.top-next.top,sx=old.width/next.width,sy=old.height/next.height;
 if(Math.abs(dx)+Math.abs(dy)+Math.abs(sx-1)*100+Math.abs(sy-1)*100<1)return;
 hingeAnimations.push(el.animate([{transformOrigin:'top left',transform:'translate('+dx+'px,'+dy+'px) scale('+sx+','+sy+')'},{transformOrigin:'top left',transform:'none'}],{duration,easing}));
 });if(hingeChanged)main.querySelectorAll('.home-month,.home-workout-expanded').forEach(el=>{if(el.getClientRects().length&&el.animate)hingeAnimations.push(el.animate([{opacity:.45},{opacity:1}],{duration,easing}))});
 }
 if(document.body.dataset.layout!=='folded-landscape'){
  railPanel.hidden=true;delete document.body.dataset.calibrating;document.body.style.removeProperty('--calibration-right');
 }else if(document.body.dataset.calibrating)railMeasure();
}
for(const type of ['resize','orientationchange','pageshow'])addEventListener(type,detectRotation);
screen.orientation?.addEventListener('change',detectRotation);
window.visualViewport?.addEventListener('resize',detectRotation);
navigator.devicePosture?.addEventListener('change',detectRotation);
matchMedia('(orientation:landscape)').addEventListener('change',detectRotation);
matchMedia('(device-posture: folded)').addEventListener('change',detectRotation);
FormPosture.listen(detectRotation);
detectRotation();

function refreshHomeClock(){if(page!=='Home'||showDiagnostics||document.hidden)return;const now=new Date(),p=homeProfile(),g=main.querySelector('.home-greeting-trigger'),date=main.querySelector('.home-date span'),weekday=main.querySelector('.home-date strong');if(!g||!date||!weekday)return;const nextDate=now.toLocaleDateString(undefined,{month:'long',day:'numeric'}),nextWeekday=now.toLocaleDateString(undefined,{weekday:'long'});if(date.textContent!==nextDate||weekday.textContent!==nextWeekday){render();return}const next=FormHome.greeting(now)+(p.name?', '+p.name:'')+'.';if(g.textContent!==next)g.textContent=next}addEventListener('focus',refreshHomeClock);document.addEventListener('visibilitychange',refreshHomeClock);setInterval(refreshHomeClock,60000);

// Shared geometry diagnostic preview.
(()=>{const mode=document.getElementById('fl1-preview-mode'),orientation=document.getElementById('duo-preview-orientation'),canvas=document.getElementById('fl1-preview-canvas'),toggle=document.getElementById('duo-preview-guides');if(!canvas)return;
function draw(){const d=FormDuoGeometry[orientation.value],native=mode.value==='native',g=toggle.checked,{w,h,side,excluded:e}=d,t=!native&&side==='top'?e:0,x=!native&&side==='left'?e:d.content,right=w-(!native&&side==='right'?e:0),rail=w>h&&h<530,edge=right-(rail?80:16),wide=w>h,a=wide?(edge-x-12)*.4:edge-x,sy=t+158,ah=wide?Math.min(262,h-t-180):140,bx=wide?x+a+12:x,by=wide?sy:sy+ah+12,now=new Date(),boundary=side==='top'?'M0 '+e+'H'+w:'M'+(side==='left'?e:w-e)+' 0V'+h;
const line=(p,c,dash='5 4')=>'<path d="'+p+'" stroke="'+c+'" stroke-width="1.5" stroke-dasharray="'+dash+'" fill="none"/>';
const text=(x,y,s,size=16,color='#111',anchor='start')=>'<text x="'+x+'" y="'+y+'" font-size="'+size+'" fill="'+color+'" text-anchor="'+anchor+'" font-family="system-ui">'+s+'</text>';
const rect=(x,y,w,h,c,r=0)=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="'+r+'" fill="'+c+'"/>';
let s=rect(0,0,w,h,'#f2f2f7',28);if(!native)s+=rect(side==='right'?w-e:0,0,side==='top'?w:e,side==='top'?e:h,'#d1d1d6');if(d.camera)s+='<circle cx="'+d.camera[0]+'" cy="'+d.camera[1]+'" r="18.5" fill="#111"/>';
s+=rect(d.headline,t+32,3,32,'#007aff',1.5)+text(d.headline+13.5,t+58,'FORM',28)+text(d.headline+13.5,t+82,'Train with focus, follow your progress',12,'#636366')+text(edge,t+43,now.toLocaleDateString('en',{weekday:'long'}),15,'#111','end')+text(edge,t+65,now.toLocaleDateString('en',{month:'long',day:'numeric'}),12,'#636366','end')+text(x,t+131,'Good afternoon.',22)+rect(x,sy,a,ah,'#0066cc',20)+text(x+12,sy+32,'Ready to train?',17,'white')+text(x+12,sy+56,'Choose your workout',12,'white')+rect(bx,by,edge-bx,wide?ah:190,'white',20)+text(bx+12,by+32,'Consistency streak',16)+text(bx+12,by+58,'0 of 7 days on track',13,'#636366')+text(bx+12,by+100,'0',32,'#ff9500');
s+=rail?rect(edge+16,h/2-90,48,180,'white',24):rect(x,h-70,edge-x,54,'white',27);
const icons=['M-9 0L0 -9L9 0V9H3V1H-3V9H-9Z','M-10 -5V5M-6 -8V8M6 -8V8M10 -5V5M-6 0H6','M-9 9V1M0 9V-4M9 9V-9','M-9 10Q-9 0 0 0Q9 0 9 10M0 -2a5 5 0 1 0 0 -10a5 5 0 1 0 0 10'];icons.forEach((p,i)=>{s+='<g transform="translate('+(rail?edge+40:x+(edge-x)*(i+.5)/4)+' '+(rail?h/2-66+i*44:h-43)+')">'+line(p,i===0?'#007aff':'#636366','none')+'</g>'});
if(g){s+=line(boundary,'#007aff',native?'5 4':'none')+line('M'+x+' 0V'+h+'M'+edge+' 0V'+h+'M'+x+' '+sy+'H'+edge,'#16a34a')+line('M0 '+(t+48)+'H'+w+'M'+d.headline+' 0V'+h,'#a855f7');if(d.camera){const [cx,cy]=d.camera;s+=line('M'+(cx-18.5)+' 0V'+h+'M'+(cx+18.5)+' 0V'+h+'M0 '+(cy-18.5)+'H'+w+'M0 '+(cy+18.5)+'H'+w,'#ff9500')+line('M'+cx+' 0V'+h+'M0 '+cy+'H'+w,'#a855f7')}}
canvas.innerHTML='<svg viewBox="-8 -8 '+(w+16)+' '+(h+16)+'" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto"><rect width="'+w+'" height="'+h+'" rx="28" fill="#111" stroke="#a9abb0" stroke-width="12"/><defs><clipPath id="duo-preview-clip"><rect width="'+w+'" height="'+h+'" rx="28"/></clipPath></defs><g clip-path="url(#duo-preview-clip)">'+s+'</g></svg><p>'+w+' × '+h+' pt · '+(native?'Native simulation':e+' pt excluded on '+side)+'</p>'}
[mode,orientation,toggle].forEach(el=>el.addEventListener('change',draw));draw()})();
(()=>{const toggle=document.getElementById('viewport-outline-enabled');if(!toggle)return;try{toggle.checked=localStorage.getItem('form.viewportOutline')!=='off'}catch{}function apply(){document.body.dataset.viewportOutline=toggle.checked?'on':'off';try{localStorage.setItem('form.viewportOutline',document.body.dataset.viewportOutline)}catch{}}toggle.addEventListener('change',apply);apply()})();

/* Build 190: live diagnostic overlay, independent of app layout. */
(()=>{
const lab=document.getElementById('viewport-lab'),panel=lab.querySelector('.viewport-readings');
const style=document.createElement('style');style.textContent=`
body[data-diagnostics=true] main,body[data-diagnostics=true] nav.nav{visibility:visible!important}
#viewport-lab{background:transparent;pointer-events:none;isolation:auto}
#viewport-lab .viewport-grid{display:none}
#viewport-lab .viewport-readings{pointer-events:auto;inset:auto max(12px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) auto;width:min(320px,calc(100% - 24px));max-height:65dvh;margin:0;background:rgba(250,250,252,.96);border-radius:18px;box-shadow:0 8px 32px #0002}
#viewport-lab .viewport-readings label{display:flex;align-items:center;gap:8px;padding:5px 0}
#viewport-lab .viewport-readings header button{font:600 13px system-ui}
#viewport-lab[data-collapsed=true] .viewport-readings>:not(header){display:none}
#viewport-lab[data-collapsed=true] .viewport-readings{width:auto;min-width:0;padding:6px 10px}
#viewport-lab[data-collapsed=true] header>:not(:last-child){display:none}
#live-layout-guides{position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:99999}
body:not([data-diagnostics=true]) #live-layout-guides{display:none}
body[data-diagnostics=true]:not([data-live-safe=true]) #safe-area-overlay{visibility:hidden}
`;document.head.append(style);
const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.id='live-layout-guides';svg.setAttribute('aria-hidden','true');document.body.append(svg);
const header=panel.querySelector('header');const collapse=document.createElement('button');collapse.type='button';collapse.textContent='Collapse';header.append(collapse);collapse.onclick=()=>{const v=lab.dataset.collapsed!=='true';lab.dataset.collapsed=String(v);collapse.textContent=v?'Expand':'Collapse'};
const controls=document.createElement('section');controls.innerHTML='<h3>Alignment guides</h3>';header.after(controls);
const groups=[['Content','#16a34a','.home-dashboard,.form-page'],['Headline','#a855f7','.home-brand,.home-greeting'],['Cards','#16a34a','.home-workout-card,.home-streak-card,.home-primary'],['Navigation','#a855f7','nav.nav'],['Safe areas','#ef4444','']];
const flags={};for(const [name,color] of groups){const l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=name!=='Safe areas';try{const saved=localStorage.getItem('form.guide.'+name);if(saved!==null)i.checked=saved==='true'}catch{}flags[name]=i;l.append(i,document.createTextNode(name));l.style.color=color;controls.append(l);i.onchange=()=>{try{localStorage.setItem('form.guide.'+name,String(i.checked))}catch{}draw()}}
function draw(){svg.replaceChildren();document.body.dataset.liveSafe=String(flags['Safe areas'].checked);if(lab.hidden)return;const w=document.documentElement.clientWidth,h=document.documentElement.clientHeight;svg.setAttribute('viewBox','0 0 '+w+' '+h);for(const [name,color,selector] of groups){if(!selector||!flags[name].checked)continue;for(const el of document.querySelectorAll(selector)){const r=el.getBoundingClientRect();if(!r.width||!r.height)continue;const p=document.createElementNS(svg.namespaceURI,'path');p.setAttribute('d','M'+r.left+' 0V'+h+' M'+r.right+' 0V'+h+' M0 '+r.top+'H'+w+' M0 '+r.bottom+'H'+w);p.setAttribute('stroke',color);p.setAttribute('stroke-width','0.8');p.setAttribute('stroke-dasharray','4 4');p.setAttribute('fill','none');svg.append(p)}}}
new MutationObserver(()=>requestAnimationFrame(draw)).observe(lab,{attributes:true,attributeFilter:['hidden']});new ResizeObserver(draw).observe(main);addEventListener('resize',draw);main.addEventListener('scroll',draw,{passive:true});document.addEventListener('click',()=>requestAnimationFrame(draw));draw();
})();
